'use client';

import {useActionState,useState} from 'react';
import {saveSellerApplication} from '@/app/vendor/actions';
import {VendorMediaPicker,type MediaChoice} from '@/components/vendor-forms';
import {uploadEstablishmentPhoto,uploadSellerDocument} from '@/services/seller-application-upload';

type Application=Record<string,unknown>|null;
type Cuisine={id:string;name:string};
const steps=['Vous','Votre établissement','Photos','Documents','Vérification'];

function FileField({applicationId,kind,label,multiple=false,imagesOnly=false}:{applicationId?:string;kind:string;label:string;multiple?:boolean;imagesOnly?:boolean}){
 const[files,setFiles]=useState<string[]>([]);const[busy,setBusy]=useState(false);const[error,setError]=useState('');
 async function upload(chosen:File[]){if(!applicationId){setError('Enregistrez d’abord le brouillon, puis ajoutez ce fichier.');return}setBusy(true);setError('');try{for(const file of chosen){const name=imagesOnly?await uploadEstablishmentPhoto(applicationId,file):await uploadSellerDocument(applicationId,file,kind,label);setFiles(current=>[...current,name])}}catch(reason){setError(reason instanceof Error?reason.message:'Envoi impossible.')}finally{setBusy(false)}}
 return <label className="application-file"><span>{label}</span><input type="file" multiple={multiple} accept={imagesOnly?'image/jpeg,image/png,image/webp':'image/jpeg,image/png,image/webp,application/pdf'} onChange={event=>upload(Array.from(event.target.files??[]))}/><b>{busy?'Envoi…':files.length?files.join(', '):'Choisir un fichier'}</b><small>{imagesOnly?'JPG, PNG ou WebP':'JPG, PNG, WebP ou PDF'} · 15 Mo maximum</small>{error?<em className="field-error">{error}</em>:null}</label>
}

export function ApplicationForm({application,cuisines,media,documentKinds=[]}:{application:Application;cuisines:Cuisine[];media:MediaChoice[];documentKinds?:string[]}){
 const[state,action,pending]=useActionState(saveSellerApplication,{});const[step,setStep]=useState(0);const applicationId=state.applicationId??(application?.id?String(application.id):undefined);const selected=Array.isArray(application?.cuisine_notes)?application.cuisine_notes.map(String):[];const hasIdentity=documentKinds.includes('identity_front');const hasPhoto=Array.isArray(application?.establishment_photo_paths)&&application.establishment_photo_paths.length>0;
 return <form action={action} className="vendor-form application-form">
  <ol className="application-progress" aria-label="Progression">{steps.map((label,index)=><li key={label} className={index===step?'active':index<step?'done':''}><button type="button" onClick={()=>setStep(index)}><span>{index+1}</span>{label}</button></li>)}</ol>
  <section hidden={step!==0}><h2>Votre identité</h2><p className="muted">Ces informations servent uniquement à vérifier votre demande et ne seront jamais publiques.</p><div className="vendor-form-grid"><label className="field full"><span>Nom et prénoms</span><input name="applicant_name" defaultValue={String(application?.applicant_name??'')} required/></label><label className="field"><span>Téléphone</span><input name="phone" type="tel" defaultValue={String(application?.phone??'')} required/></label><label className="field"><span>WhatsApp <small>facultatif</small></span><input name="whatsapp" type="tel" defaultValue={String(application?.whatsapp??'')}/></label><label className="field full"><span>Email</span><input name="email" type="email" defaultValue={String(application?.email??'')} required/></label><label className="field"><span>Adresse</span><input name="applicant_address" defaultValue={String(application?.applicant_address??'')} required/></label><label className="field"><span>Commune</span><input name="applicant_commune" defaultValue={String(application?.applicant_commune??'')} required/></label></div><h3>Pièce d’identité</h3><div className="vendor-form-grid"><label className="field"><span>Type de pièce</span><select name="identity_type" defaultValue={String(application?.identity_type??'cni')}><option value="cni">CNI</option><option value="passport">Passeport</option><option value="identity_certificate">Attestation d’identité</option><option value="drivers_license">Permis de conduire</option><option value="other">Autre document officiel</option></select></label><label className="field"><span>Numéro de la pièce <small>facultatif</small></span><input name="identity_number" defaultValue={String(application?.identity_number??'')}/></label><FileField applicationId={applicationId} kind="identity_front" label={hasIdentity?'Remplacer le recto':'Recto de la pièce *'}/><FileField applicationId={applicationId} kind="identity_back" label="Verso, si nécessaire"/></div></section>
  <section hidden={step!==1}><h2>Votre établissement</h2><div className="vendor-form-grid"><label className="field full"><span>Nom du restaurant</span><input name="restaurant_name" defaultValue={String(application?.restaurant_name??'')} required/></label><label className="field full"><span>Description</span><textarea name="description" rows={4} defaultValue={String(application?.description??'')} placeholder="Décrivez simplement votre cuisine et vos spécialités."/></label><label className="field full"><span>Adresse du restaurant</span><input name="address" defaultValue={String(application?.address??'')}/></label><label className="field"><span>Commune / zone</span><input name="commune" defaultValue={String(application?.commune??'')}/></label><label className="field"><span>Lien Maps <small>facultatif</small></span><input name="maps_url" type="url" defaultValue={String(application?.maps_url??'')}/></label><label className="field"><span>Latitude <small>facultatif</small></span><input name="latitude" type="number" step="any" defaultValue={String(application?.latitude??'')}/></label><label className="field"><span>Longitude <small>facultatif</small></span><input name="longitude" type="number" step="any" defaultValue={String(application?.longitude??'')}/></label></div><fieldset className="cuisine-choices"><legend>Types de cuisine</legend>{cuisines.map(cuisine=><label key={cuisine.id}><input type="checkbox" name="cuisine_types" value={cuisine.name} defaultChecked={selected.includes(cuisine.name)}/><span>{cuisine.name}</span></label>)}</fieldset><div className="option-checks"><label><input type="checkbox" name="delivery_available" defaultChecked={application?.delivery_available!==false}/><span>Livraison disponible</span></label><label><input type="checkbox" name="pickup_available" defaultChecked={application?.pickup_available!==false}/><span>Retrait disponible</span></label></div></section>
  <section hidden={step!==2}><h2>Photos de l’établissement</h2><p className="muted">Ajoutez une image claire de votre boutique ou de votre espace de préparation.</p><div className="vendor-photo-grid"><div><strong>Logo</strong><VendorMediaPicker type="logo" pathName="logo_path" initialPath={String(application?.logo_path??'')} items={media}/></div><div><strong>Photo de couverture</strong><VendorMediaPicker type="cover" pathName="cover_path" initialPath={String(application?.cover_path??'')} items={media}/></div></div><FileField applicationId={applicationId} kind="establishment_photo" label={hasPhoto?'Ajouter d’autres photos':'Ajouter des photos de votre établissement *'} multiple imagesOnly/></section>
  <section hidden={step!==3}><h2>Documents de votre activité</h2><p className="muted">Ces justificatifs sont facultatifs et restent privés.</p><div className="vendor-form-grid"><FileField applicationId={applicationId} kind="business_registry" label="RCCM / registre de commerce"/><FileField applicationId={applicationId} kind="business_registration" label="Immatriculation de l’entreprise"/><label className="field full"><span>Nom d’un autre document</span><input name="other_document_name" placeholder="Ex. Autorisation d’ouverture"/></label><FileField applicationId={applicationId} kind="other_business" label="Autre justificatif professionnel"/></div></section>
  <section hidden={step!==4}><h2>Vérification</h2><div className="application-review"><p><strong>Avant l’envoi</strong></p><ul><li>Votre identité est complète.</li><li>Le restaurant et ses coordonnées sont renseignés.</li><li>Une pièce d’identité et une photo réelle sont jointes.</li><li>Les documents privés ne seront accessibles qu’à vous et aux administrateurs autorisés.</li></ul></div></section>
  {state.error?<div className="form-feedback error" role="alert">{state.error}</div>:null}{state.ok?<div className="form-feedback success" role="status">✓ {state.message}</div>:null}<div className="application-actions"><button type="submit" className="btn btn-outline" name="intent" value="draft" disabled={pending}>Enregistrer le brouillon</button>{step>0?<button type="button" className="btn btn-outline" onClick={()=>setStep(value=>value-1)}>Précédent</button>:null}{step<4?<button type="button" className="btn btn-dark" onClick={()=>setStep(value=>value+1)}>Continuer</button>:<button type="submit" className="btn btn-dark" name="intent" value="submit" disabled={pending}>{pending?'Envoi…':'Envoyer ma demande'}</button>}</div>
 </form>
}
